mkitem!{macro_rules ! forward_iterator { ($ name : ident : $ elem : ident , $ iter_of : ty) => { # [stable (feature = "rust1" , since = "1.0.0")] impl <'a , $ elem , P > Iterator for $ name <'a , $ elem , P > where P : FnMut (& T) -> bool , { type Item = $ iter_of ; # [inline] fn next (& mut self) -> Option <$ iter_of > { self . inner . next () } # [inline] fn size_hint (& self) -> (usize , Option < usize >) { self . inner . size_hint () } } # [stable (feature = "fused" , since = "1.26.0")] impl <'a , $ elem , P > FusedIterator for $ name <'a , $ elem , P > where P : FnMut (& T) -> bool { } } ; }}